function Order(id) {
  this.id = id;
  Order.made += 1;
}

Order.made = 0;
Order.prototype.made = 100;

const a = new Order(1);
const b = new Order(2);

console.log(Order.made, a.made, b.id);
console.log(Object.hasOwn(a, "made"), Object.hasOwn(Order, "made"));
console.log(Order.prototype.constructor.made, Order.length);
console.log(a.length, Order.prototype.id);
